#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

enum { MAX_CAPACITY = 8 };

struct Record {
    size_t id;
    int value;
};

struct Queue {
    struct Record *items;
    size_t used;
    size_t capacity;
};

struct GrowthPolicy {
    unsigned attempts;
    unsigned fail_at;
};

static int reserve(struct Queue *queue, struct GrowthPolicy *policy)
{
    if (queue->capacity == 0 || queue->capacity > MAX_CAPACITY / 2) {
        return 0;
    }
    size_t next_capacity = queue->capacity * 2;
    if (next_capacity > SIZE_MAX / sizeof *queue->items) {
        return 0;
    }
    ++policy->attempts;
    if (policy->attempts == policy->fail_at) {
        return 0;
    }
    struct Record *next = realloc(queue->items, next_capacity * sizeof *queue->items);
    if (next == NULL) {
        return 0;
    }
    queue->items = next;
    queue->capacity = next_capacity;
    return 1;
}

static int append(struct Queue *queue, struct GrowthPolicy *policy, int value)
{
    if (queue->used == queue->capacity && !reserve(queue, policy)) {
        return 0;
    }
    queue->items[queue->used] = (struct Record){.id = queue->used + 1, .value = value};
    ++queue->used;
    return 1;
}

static long total(const struct Queue *queue)
{
    long sum = 0;
    for (size_t i = 0; i < queue->used; ++i) {
        sum += queue->items[i].value;
    }
    return sum;
}

static void destroy(struct Queue *queue)
{
    free(queue->items);
    *queue = (struct Queue){0};
}

int main(void)
{
    struct Queue queue = {malloc(sizeof(struct Record)), 1, 1};
    if (queue.items == NULL) {
        puts("allocation-failed");
        return 0;
    }
    queue.items[0] = (struct Record){.id = 1, .value = 5};
    struct GrowthPolicy policy = {.attempts = 0, .fail_at = 2};
    int ok = append(&queue, &policy, 8) && append(&queue, &policy, 13);
    printf("%s %zu %zu %ld\n", ok ? "ok" : "allocation-failed",
           queue.used, queue.capacity, total(&queue));
    for (size_t i = 0; i < queue.used; ++i) {
        printf("%zu:%d\n", queue.items[i].id, queue.items[i].value);
    }
    destroy(&queue);
    return 0;
}

